# Términos añadidos en la ampliación de 2026
GLOSARIO += [
    ('ADN antiguo', 'ADN recuperado de restos de hace cientos o miles de años, como huesos o dientes. Suele estar muy fragmentado y contaminado. <a href="../evolucion-humana/atapuerca-y-el-adn-antiguo/">Leer más</a>.'),
    ('ADN circulante', 'Fragmentos de ADN que flotan libres en la sangre. Una parte puede venir de un tumor o, en el embarazo, de la placenta. <a href="../genetica-y-cancer/biopsia-liquida/">Leer más</a>.'),
    ('ADN recombinante', 'ADN creado en el laboratorio uniendo fragmentos de distintas procedencias, a menudo de especies diferentes. <a href="../personajes/paul-berg/">Leer más</a>.'),
    ('Aneuploidía', 'Número anormal de cromosomas en una célula, por exceso o por defecto, como en la trisomía 21 o el síndrome de Turner. <a href="../enfermedades/sindrome-de-turner/">Leer más</a>.'),
    ('Anticuerpo monoclonal', 'Proteína del sistema inmunitario fabricada en el laboratorio para reconocer una diana concreta, como una proteína de un tumor. <a href="../genetica-y-cancer/oncologia-de-precision/">Leer más</a>.'),
    ('Apoptosis', 'Muerte celular programada: un mecanismo ordenado por el que el organismo elimina células dañadas o innecesarias. <a href="../genetica-y-cancer/como-nace-un-tumor/">Leer más</a>.'),
    ('Árbol genealógico', 'Dibujo con símbolos estándar que muestra los miembros de una familia y quién tiene una enfermedad. Ayuda a deducir cómo se hereda. <a href="../herencia/patrones-de-herencia/">Leer más</a>.'),
    ('Bacteriófago', 'Virus que infecta bacterias. Su estudio dio pistas clave sobre el ADN y sobre CRISPR.'),
    ('Biobanco', 'Colección organizada de muestras biológicas y datos de muchas personas para investigación, con su consentimiento. <a href="../genetica-y-sociedad/privacidad-de-los-datos-geneticos/">Leer más</a>.'),
    ('Biopsia líquida', 'Análisis de sangre que busca ADN de un tumor para diagnosticarlo o seguir su evolución sin cirugía. <a href="../genetica-y-cancer/biopsia-liquida/">Leer más</a>.'),
    ('Cas9', 'Proteína bacteriana que corta el ADN en el punto que le indica un ARN guía. Es la herramienta más usada de CRISPR. <a href="../tratamientos/crispr-explicado/">Leer más</a>.'),
    ('Célula germinal', 'Célula que da lugar a óvulos o espermatozoides. Los cambios en ella pueden pasar a los hijos.'),
    ('Célula madre', 'Célula capaz de dividirse y de convertirse en otros tipos de células.'),
    ('Centrómero', 'Zona estrecha de un cromosoma que une sus dos brazos y por donde lo arrastra la célula al dividirse. <a href="../lo-basico/genes-cromosomas-y-genoma/">Leer más</a>.'),
    ('Clon', 'Organismo o célula con el mismo ADN que otro del que procede. <a href="../plantas-y-animales/clonacion-animal/">Leer más</a>.'),
    ('Codominancia', 'Situación en la que las dos variantes de un gen se expresan a la vez, como en el grupo sanguíneo AB. <a href="../rasgos-cotidianos/grupo-sanguineo/">Leer más</a>.'),
    ('Colágeno', 'La proteína más abundante del cuerpo, que da resistencia a la piel, los huesos, los tendones y los vasos. <a href="../enfermedades/sindromes-de-ehlers-danlos/">Leer más</a>.'),
    ('Cromátida', 'Cada una de las dos copias idénticas de un cromosoma tras duplicarse, unidas por el centrómero.'),
    ('Cromatina', 'Mezcla de ADN y proteínas que forma los cromosomas. Puede estar más o menos compactada. <a href="../herencia/epigenetica/">Leer más</a>.'),
    ('Deleción', 'Pérdida de un fragmento de ADN, desde una letra hasta un trozo de cromosoma. <a href="../lo-basico/mutaciones-y-variantes/">Leer más</a>.'),
    ('Denisovanos', 'Grupo humano extinto conocido sobre todo por su ADN, que dejó huella en el genoma de poblaciones de Asia y Oceanía. <a href="../evolucion-humana/neandertales-y-denisovanos/">Leer más</a>.'),
    ('Deriva genética', 'Cambio al azar de la frecuencia de las variantes genéticas de una generación a otra, más fuerte en poblaciones pequeñas. <a href="../evolucion-humana/el-origen-africano/">Leer más</a>.'),
    ('Diagnóstico prenatal', 'Pruebas para saber si un feto tiene una enfermedad genética o cromosómica. <a href="../embarazo-y-reproduccion/diagnostico-prenatal-paso-a-paso/">Leer más</a>.'),
    ('Disomía uniparental', 'Situación en la que las dos copias de un cromosoma vienen del mismo progenitor. <a href="../enfermedades/sindromes-de-prader-willi-y-angelman/">Leer más</a>.'),
    ('Doble hélice', 'Forma del ADN: dos cadenas enrolladas una sobre otra, unidas por sus bases. <a href="../lo-basico/que-es-el-adn/">Leer más</a>.'),
    ('Duplicación', 'Copia extra de un fragmento de ADN. <a href="../lo-basico/mutaciones-y-variantes/">Leer más</a>.'),
    ('Efecto fundador', 'Alta frecuencia de una variante en una población que desciende de unos pocos antepasados que la llevaban. <a href="../enfermedades-raras/que-es-una-enfermedad-rara/">Leer más</a>.'),
    ('Electroforesis', 'Técnica que separa fragmentos de ADN o proteínas según su tamaño haciéndolos avanzar por un gel con corriente eléctrica. <a href="../genetica-forense/huellas-geneticas/">Leer más</a>.'),
    ('Enfermedad rara', 'En Europa, la que afecta a menos de 5 de cada 10.000 personas. Unas tres de cada cuatro tienen origen genético. <a href="../enfermedades-raras/que-es-una-enfermedad-rara/">Leer más</a>.'),
    ('Enzima', 'Proteína que acelera una reacción química del organismo. <a href="../lo-basico/de-gen-a-proteina/">Leer más</a>.'),
    ('Enzima de restricción', 'Enzima bacteriana que corta el ADN en una secuencia concreta. Fue clave para la ingeniería genética.'),
    ('Especificidad', 'Capacidad de una prueba para dar negativo en quien no tiene la enfermedad. <a href="../diagnostico/como-leer-un-resultado-genetico/">Leer más</a>.'),
    ('Expresividad variable', 'Diferencias en la gravedad o los síntomas de una misma enfermedad genética entre personas con la misma variante. <a href="../enfermedades/neurofibromatosis-tipo-1/">Leer más</a>.'),
    ('Fecundación in vitro', 'Unión del óvulo y el espermatozoide en el laboratorio, con transferencia posterior del embrión al útero. <a href="../embarazo-y-reproduccion/fiv-con-diagnostico-preimplantacional/">Leer más</a>.'),
    ('Gameto', 'Célula reproductora: óvulo o espermatozoide. Tiene la mitad de cromosomas que el resto de células. <a href="../embarazo-y-reproduccion/donacion-de-gametos/">Leer más</a>.'),
    ('Gemelos idénticos', 'Gemelos que proceden de un mismo embrión que se dividió; comparten casi todo su ADN. <a href="../preguntas-frecuentes/los-gemelos-tienen-el-mismo-adn/">Leer más</a>.'),
    ('Gen supresor de tumores', 'Gen que frena la división celular o repara daños. Si se pierden sus dos copias, favorece el cáncer. <a href="../genetica-y-cancer/como-nace-un-tumor/">Leer más</a>.'),
    ('Genealogía genética', 'Uso de bases de datos de ADN de particulares para encontrar parientes lejanos, incluso para identificar sospechosos. <a href="../genetica-forense/genealogia-genetica/">Leer más</a>.'),
    ('Haplogrupo', 'Grupo de personas que comparten un antepasado común por línea materna (ADN mitocondrial) o paterna (cromosoma Y). <a href="../evolucion-humana/el-origen-africano/">Leer más</a>.'),
    ('Haplotipo', 'Conjunto de variantes cercanas en un cromosoma que suelen heredarse juntas.'),
    ('Hemicigoto', 'Que tiene una sola copia de un gen, como los hombres para los genes del cromosoma X. <a href="../herencia/patrones-de-herencia/">Leer más</a>.'),
    ('Huella genética', 'Perfil de marcadores de ADN que permite distinguir a una persona de casi todas las demás. <a href="../genetica-forense/huellas-geneticas/">Leer más</a>.'),
    ('Impulsor genético', 'Construcción genética que se hereda en casi toda la descendencia y puede extenderse por una población. <a href="../plantas-y-animales/mosquitos-modificados-contra-la-malaria/">Leer más</a>.'),
    ('Inactivación del X', 'Apagado al azar de uno de los dos cromosomas X en cada célula de las mujeres. <a href="../personajes/mary-lyon/">Leer más</a>.'),
    ('Inserción', 'Entrada de una o más letras extra en una secuencia de ADN. <a href="../lo-basico/mutaciones-y-variantes/">Leer más</a>.'),
    ('Inversión', 'Fragmento de cromosoma que se ha dado la vuelta.'),
    ('Lisosoma', 'Orgánulo de la célula lleno de enzimas que descomponen y reciclan moléculas. <a href="../enfermedades/tay-sachs-y-enfermedades-lisosomales/">Leer más</a>.'),
    ('Marcador genético', 'Variante de ADN de posición conocida que sirve como señal para seguir la herencia o identificar personas.'),
    ('Mendeliano', 'Rasgo o enfermedad que depende de un solo gen y sigue las leyes de Mendel. <a href="../herencia/las-leyes-de-mendel/">Leer más</a>.'),
    ('Metástasis', 'Extensión de un cáncer desde su lugar de origen a otros órganos. <a href="../genetica-y-cancer/como-nace-un-tumor/">Leer más</a>.'),
    ('Mitocondria', 'Orgánulo que produce la energía de la célula. Tiene su propio ADN, heredado de la madre.'),
    ('Mitosis', 'División de una célula en dos células hijas con el mismo número de cromosomas.'),
    ('Neandertales', 'Especie humana que vivió en Europa y Asia hasta hace unos 40.000 años y se cruzó con nuestros antepasados. <a href="../evolucion-humana/neandertales-y-denisovanos/">Leer más</a>.'),
    ('Oligonucleótido antisentido', 'Fragmento corto de ARN o ADN sintético que se une a un ARN concreto para cambiar cómo se usa o destruirlo. <a href="../enfermedades/ela-hereditaria/">Leer más</a>.'),
    ('Oncogén', 'Gen que, al alterarse, acelera la división celular y favorece el cáncer. <a href="../genetica-y-cancer/como-nace-un-tumor/">Leer más</a>.'),
    ('Organismo modificado genéticamente', 'Ser vivo cuyo ADN se ha cambiado con técnicas de ingeniería genética. <a href="../plantas-y-animales/transgenicos-y-edicion-de-cultivos/">Leer más</a>.'),
    ('Paleogenómica', 'Estudio de genomas completos de organismos antiguos o extinguidos. <a href="../personajes/svante-paabo/">Leer más</a>.'),
    ('Pleiotropía', 'Efecto de un mismo gen sobre varios rasgos u órganos distintos. <a href="../enfermedades/sindrome-de-marfan/">Leer más</a>.'),
    ('Poligénico', 'Rasgo que depende de muchos genes, cada uno con un efecto pequeño, como la altura. <a href="../rasgos-cotidianos/la-altura/">Leer más</a>.'),
    ('Polimorfismo', 'Variante genética frecuente en la población, normalmente sin efecto perjudicial.'),
    ('Proteína', 'Molécula formada por una cadena de aminoácidos que realiza casi todas las funciones de la célula. <a href="../lo-basico/de-gen-a-proteina/">Leer más</a>.'),
    ('Quimera', 'Organismo formado por células de dos individuos genéticamente distintos.'),
    ('Recombinación', 'Intercambio de fragmentos entre cromosomas homólogos durante la meiosis, que mezcla los genes de los padres. <a href="../preguntas-frecuentes/por-que-los-hermanos-no-son-iguales/">Leer más</a>.'),
    ('Replicación', 'Copia del ADN antes de que la célula se divida. <a href="../lo-basico/que-es-el-adn/">Leer más</a>.'),
    ('ARN mensajero', 'Copia de un gen en forma de ARN que lleva las instrucciones hasta los ribosomas para fabricar una proteína. <a href="../personajes/katalin-kariko/">Leer más</a>.'),
    ('Secuenciación masiva', 'Técnicas que leen millones de fragmentos de ADN a la vez y permiten estudiar genomas completos de forma rápida y barata. <a href="../diagnostico/paneles-exoma-y-genoma/">Leer más</a>.'),
    ('Selección natural', 'Proceso por el que las variantes que favorecen la supervivencia y la reproducción se vuelven más frecuentes. <a href="../rasgos-cotidianos/intolerancia-a-la-lactosa/">Leer más</a>.'),
    ('Sensibilidad', 'Capacidad de una prueba para dar positivo en quien sí tiene la enfermedad. <a href="../diagnostico/como-leer-un-resultado-genetico/">Leer más</a>.'),
    ('STR', 'Repeticiones cortas en tándem: secuencias de pocas letras repetidas un número de veces que varía entre personas. Base de los perfiles forenses. <a href="../genetica-forense/huellas-geneticas/">Leer más</a>.'),
    ('Síndrome', 'Conjunto de signos y síntomas que aparecen juntos y caracterizan una enfermedad.'),
    ('Telómero', 'Extremo de un cromosoma que lo protege y se acorta con cada división celular.'),
    ('Terapia dirigida', 'Tratamiento contra el cáncer diseñado para actuar sobre una alteración genética concreta del tumor. <a href="../genetica-y-cancer/oncologia-de-precision/">Leer más</a>.'),
    ('Transgénico', 'Organismo al que se ha añadido un gen de otra especie. <a href="../plantas-y-animales/transgenicos-y-edicion-de-cultivos/">Leer más</a>.'),
    ('Triplete', 'Grupo de tres letras del ADN o el ARN. Un codón es un triplete que corresponde a un aminoácido. <a href="../personajes/har-gobind-khorana/">Leer más</a>.'),
    ('Virus adenoasociado', 'Virus inofensivo que se usa como vector en muchas terapias génicas. <a href="../tratamientos/terapia-genica/">Leer más</a>.'),
    ('Penetrancia incompleta', 'Cuando no todas las personas con una variante patogénica desarrollan la enfermedad. <a href="../enfermedades/ela-hereditaria/">Leer más</a>.'),
]

